328	mod tests {
329	    use std::path::Path;
330	
331	    use callisto_model::{
332	        ApplyPermit, CommandError, CommandOutput, CommandRunner, PackageId, Severity, Version,
333	        VersionGrammar,
334	    };
335	
336	    use super::*;
337	    use crate::plan::{PlannedBump, VersionPlan};
338	
339	    /// A no-op runner that always reports success for any git command.
340	    struct NoopRunner;
341	
342	    impl CommandRunner for NoopRunner {
343	        fn run(
344	            &self,
345	            _program: &str,
346	            _args: &[&str],
347	            _cwd: &Path,
348	        ) -> Result<CommandOutput, CommandError> {
349	            Ok(CommandOutput {
350	                exit_code: Some(0),
351	                stdout: String::new(),
352	                stderr: String::new(),
353	            })
354	        }
355	    }
356	
357	    type CallLog = std::sync::Arc<std::sync::Mutex<Vec<(String, Vec<String>)>>>;
358	
359	    /// Records every (program, args) pair that CommandRunner::run is called with.
360	    struct RecordingRunner {
361	        #[allow(clippy::type_complexity)]
362	        calls: CallLog,
363	    }
364	
365	    impl CommandRunner for RecordingRunner {
366	        fn run(
367	            &self,
368	            program: &str,
369	            args: &[&str],
370	            _cwd: &Path,
371	        ) -> Result<CommandOutput, CommandError> {
372	            self.calls.lock().unwrap().push((
373	                program.to_string(),
374	                args.iter().map(|s| s.to_string()).collect(),
375	            ));
376	            Ok(CommandOutput {
377	                exit_code: Some(0),
378	                stdout: String::new(),
379	                stderr: String::new(),
380	            })
381	        }
382	    }
383	
384	    fn cargo_version(v: &str) -> Version {
385	        Version::parse(v, VersionGrammar::SemVer).expect("valid semver")
386	    }
387	
388	    /// When only a Cargo package is bumped, the Python lockfile (`uv.lock`)
389	    /// must NOT appear in `staged`, even when it exists on disk alongside
390	    /// `Cargo.lock`.
391	    #[test]
392	    fn cargo_only_bump_does_not_stage_python_lockfile() {
393	        let dir = tempfile::tempdir().expect("create tempdir");
394	        let root = dir.path();
395	
396	        // Place both a Cargo lockfile and a Python lockfile on disk.
397	        std::fs::write(root.join("Cargo.lock"), "# fake Cargo.lock").unwrap();
398	        std::fs::write(root.join("uv.lock"), "# fake uv.lock").unwrap();
399	
400	        let plan = VersionPlan {
401	            bumps: vec![PlannedBump {
402	                package: PackageId::parse("cargo:my-crate").expect("valid package id"),
403	                from: cargo_version("1.0.0"),
404	                to: cargo_version("1.1.0"),
405	                severity: Severity::Minor,
406	                governed_by: None,
407	                reason: None,
408	                writes: vec![], // no manifest writes — keeps test self-contained
409	            }],
410	            ..Default::default()
411	        };
412	
413	        let permit = ApplyPermit::force_for_tests();
414	        let opts = ApplyOptions::default();
415	        let outcome = apply_version_plan(root, &plan, &NoopRunner, &opts, &permit)
416	            .expect("apply_version_plan should succeed");
417	
418	        let staged_names: Vec<&str> = outcome.staged.iter().filter_map(|p| p.to_str()).collect();
419	
420	        assert!(
421	            staged_names.contains(&"Cargo.lock"),
422	            "Cargo.lock should be staged when a Cargo package is bumped, got: {staged_names:?}"
423	        );
424	        assert!(
425	            !staged_names.contains(&"uv.lock"),
426	            "uv.lock must NOT be staged when no Python package is bumped, got: {staged_names:?}"
427	        );
428	    }
429	
430	    /// When `refresh_lockfiles: true` and the plan bumps a Cargo package,
431	    /// `cargo update --workspace` must be called so that `Cargo.lock` is
432	    /// regenerated after the version bump. This prevents `cargo publish --locked`
433	    /// from failing with "lock file needs to be updated but --locked was passed".
434	    ///
435	    /// The result must appear in `ApplyOutcome::lockfile_refresh_results`.
436	    #[test]
437	    fn refresh_lockfiles_calls_cargo_update_workspace_when_cargo_bumped() {
438	        let dir = tempfile::tempdir().expect("create tempdir");
439	        let root = dir.path();
440	        std::fs::write(root.join("Cargo.lock"), "# stale lock").unwrap();
441	
442	        let calls = std::sync::Arc::new(std::sync::Mutex::new(Vec::new()));
443	        let runner = RecordingRunner {
444	            calls: std::sync::Arc::clone(&calls),
445	        };
446	
447	        let plan = VersionPlan {
448	            bumps: vec![PlannedBump {
449	                package: PackageId::parse("cargo:my-crate").expect("valid package id"),
450	                from: cargo_version("1.0.0"),
451	                to: cargo_version("1.1.0"),
452	                severity: Severity::Minor,
453	                governed_by: None,
454	                reason: None,
455	                writes: vec![],
456	            }],
457	            ..Default::default()
458	        };
459	
460	        let permit = ApplyPermit::force_for_tests();
461	        let opts = ApplyOptions {
462	            refresh_lockfiles: true,
463	        };
464	        let outcome = apply_version_plan(root, &plan, &runner, &opts, &permit)
465	            .expect("apply_version_plan should succeed");
466	
467	        let recorded = calls.lock().unwrap().clone();
468	        let cargo_update_called = recorded
469	            .iter()
470	            .any(|(prog, args)| prog == "cargo" && args.iter().any(|a| a == "update"));
471	        assert!(
472	            cargo_update_called,
473	            "cargo update must be called when refresh_lockfiles=true and Cargo package is bumped; calls: {recorded:?}"
474	        );
475	
476	        let refresh_results = outcome
477	            .lockfile_refresh_results
478	            .expect("lockfile_refresh_results must be Some when refresh ran");
479	        assert!(
480	            refresh_results
481	                .iter()
482	                .any(|r| r.filename.as_os_str() == "Cargo.lock"),
483	            "Cargo.lock must appear in lockfile_refresh_results; got: {refresh_results:?}"
484	        );
485	    }
