22	use crate::resolver::ManifestWalkResolver;
23	
24	impl ManifestWalkResolver {
25	    pub fn build<L: ProjectLocator, R: CommandRunner>(
26	        root: &Path,
27	        locator: &L,
28	        _runner: &R,
29	        cfg: &ResolvedConfig,
30	        manifest_cache: &RefCell<BTreeMap<PathBuf, Arc<dyn Manifest>>>,
31	    ) -> Result<Self, GraphError> {
32	        let projects = locator.projects()?;
33	
34	        let cargo_workspace = if root.join("Cargo.toml").exists() {
35	            if let Ok(resolver) = WorkspaceCargoResolver::load(&root.join("Cargo.toml")) {
36	                resolver.inheritance().ok().map(Arc::new)
37	            } else {
38	                None
39	            }
40	        } else {
41	            None
42	        };
43	
44	        let npm_workspace_kind = detect_npm_workspace_kind(root).ok().flatten();
45	
46	        let ctx = OpenContext {
47	            workspace_root: root,
48	            cargo_workspace,
49	            npm_workspace_kind,
50	        };
51	
52	        let mut package_manifest_decls: BTreeMap<PackageId, (PathBuf, Vec<ManifestDecl>)> =
53	            BTreeMap::new();
54	        let mut index = IdentityIndex::default();
55	        let mut diagnostics = Vec::new();
56	
57	        // Use the identity already resolved by the locator (`proj.id`) rather
58	        // than re-reading manifests through `IdentityResolver::resolve`.
59	        // The locator (e.g. `IgnoreWalkLocator`) already parsed each manifest
60	        // to discover the project, so re-resolving from scratch is redundant
61	        // and fragile — in particular, `IdentityResolver` historically had no
62	        // `Ecosystem::Pypi` arm and would crash for Python projects.
63	        let mut by_path: BTreeMap<PathBuf, Vec<(Ecosystem, PackageId)>> = BTreeMap::new();
64	        for proj in &projects {
65	            by_path
66	                .entry(proj.path.clone())
67	                .or_default()
68	                .push((proj.ecosystem, proj.id.clone()));
69	        }
70	
71	        for (rel_path, mut list) in by_path {
72	            // Explicit precedence: Cargo (0) > Npm (1) > Pypi (2) > others.
73	            // Do NOT rely on enum discriminant order -- sort by this named
74	            // priority function so the precedence survives future variant
75	            // additions to `Ecosystem`.
76	            list.sort_by_key(|a| ecosystem_primary_priority(a.0));
77	            let primary_id = list[0].1.clone();
78	
79	            index
80	                .bare
81	                .insert(primary_id.name().to_string(), primary_id.clone());
82	
83	            let mut decls = Vec::new();
84	            for (eco, _id) in &list {
85	                let (fmt, filename) = match eco {
86	                    Ecosystem::Cargo => (ManifestFormat::CargoToml, "Cargo.toml"),
87	                    Ecosystem::Npm => (ManifestFormat::PackageJson, "package.json"),
88	                    Ecosystem::Pypi => (ManifestFormat::PyprojectToml, "pyproject.toml"),
89	                    _ => (ManifestFormat::PackageJson, "package.json"),
90	                };
91	                let manifest_rel = rel_path.join(filename);
92	                if let Ok(decl) =
93	                    ManifestDecl::new(manifest_rel.clone(), ManifestRole::Canonical, fmt)
94	                {
95	                    decls.push(decl);
96	                }
97	                // For napi platform packages (os + cpu constraints in package.json),
98	                // also push a Platform-role decl so plan_publish can route them
99	                // into npm_platform_packages instead of npm_main_packages.
100	                if *eco == Ecosystem::Npm {
101	                    if let ManifestRole::Platform {
102	                        platform,
103	                        arch,
104	                        abi,
105	                    } = detect_npm_role(&root.join(&manifest_rel))
106	                    {
107	                        if let Ok(platform_decl) = ManifestDecl::new(
108	                            manifest_rel,
109	                            ManifestRole::Platform {
110	                                platform,
111	                                arch,
112	                                abi,
113	                            },
114	                            fmt,
115	                        ) {
116	                            decls.push(platform_decl);
117	                        }
118	                    }
119	                }
